class Solution {
public:
    long long maxScore(vector<int>& nums, int x) {
        vector<long long> dp(2, -1e15);
        int first_parity = nums[0] % 2;
        dp[first_parity] = nums[0];
        for (size_t i = 1; i < nums.size(); ++i) {
            int p = nums[i] % 2;
            long long v = nums[i];
            dp[p] = max(dp[p] + v, dp[1 - p] + v - x);
        }
        return max(dp[0], dp[1]);
    }
};

class Solution {
    public long maxScore(int[] nums, int x) {
        long[] dp = new long[]{(long) -1e15, (long) -1e15};
        int firstParity = nums[0] % 2;
        dp[firstParity] = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int p = nums[i] % 2;
            long v = nums[i];
            dp[p] = Math.max(dp[p] + v, dp[1 - p] + v - x);
        }
        return Math.max(dp[0], dp[1]);
    }
}

/**
 * @param {number[]} nums
 * @param {number} x
