var maxScore = function(nums, x) {
    const dp = [-Infinity, -Infinity];
    const firstParity = nums[0] % 2;
    dp[firstParity] = nums[0];
    for (let i = 1; i < nums.length; i++) {
        const p = nums[i] % 2;
        const v = nums[i];
        dp[p] = Math.max(dp[p] + v, dp[1 - p] + v - x);
    }
    return Math.max(dp[0], dp[1]);
};
